import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


triu_mm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

triu_mm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>

#include <cute/tensor.hpp>

using namespace cute;

// C = triu(A @ B), with A:[M,K] row-major, B:[K,N] row-major, C:[M,N] row-major.
__global__ static void triu_matmul_kernel(
    cute::Shape<int,int,int> shape_MNK,
    const float* __restrict__ A, cute::Stride<int, cute::Int<1>> dA,
    const float* __restrict__ B, cute::Stride<cute::Int<1>, int> dB,
    float* __restrict__ C, cute::Stride<int, cute::Int<1>> dC)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 8;
  constexpr int STAGES = 3;
  constexpr int SA_LD = BK + 4;  // padded A row stride, keeps 16B alignment
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  // Logical output view: mC (M,N) row-major
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), dC);
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));  // 256 threads, col-major
  const int m0 = blockIdx.x * BM;
  const int n0 = blockIdx.y * BN;
  const int tid = threadIdx.x;
  const int tm = tid & 15;
  const int tn = tid >> 4;
  // Fully below-diagonal CTA: triu(C)=0, no GEMM needed.
  if (m0 > n0 + BN - 1) {
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      #pragma unroll
      for (int j = 0; j < 8; ++j) {
        mC(m0 + tm + i * 16, n0 + tn + j * 16) = 0.0f;
      }
    }
    return;
  }
  __shared__ __align__(16) float smemA[STAGES][BM * SA_LD];
  __shared__ __align__(16) float smemB[STAGES][BK * BN];
  // One 16-byte cp.async per operand per thread (fully coalesced, vectorized).
  auto load_tile = [&](int kt, int buf) {
    {
      int row = tid >> 1;          // 128 rows of the A tile
      int kc  = (tid & 1) * 4;     // 2 x float4 per row
      const float* g = A + (long long)(m0 + row) * K + kt * BK + kc;
      __pipeline_memcpy_async(&smemA[buf][row * SA_LD + kc], g, 16);
    }
    {
      int kk = tid >> 5;           // 8 k-rows of the B tile
      int nn = (tid & 31) * 4;     // 32 x float4 per row
      const float* g = B + (long long)(kt * BK + kk) * N + n0 + nn;
      __pipeline_memcpy_async(&smemB[buf][kk * BN + nn], g, 16);
    }
  };
  // sA: (BM,BK) padded row-major; sB: (BN,BK) view of (BK,BN) row-major store
  auto sA_layout = make_layout(make_shape(Int<BM>{}, Int<BK>{}),
                               make_stride(Int<SA_LD>{}, Int<1>{}));
  auto sB_layout = make_layout(make_shape(Int<BN>{}, Int<BK>{}),
                               make_stride(Int<1>{}, Int<BN>{}));
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), sA_layout);
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), sA_layout);
  Tensor sA2 = make_tensor(make_smem_ptr(smemA[2]), sA_layout);
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), sB_layout);
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), sB_layout);
  Tensor sB2 = make_tensor(make_smem_ptr(smemB[2]), sB_layout);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA2 = local_partition(sA2, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCsB2 = local_partition(sB2, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCrC = make_tensor<float>(make_shape(Int<8>{}, Int<8>{}));
  clear(tCrC);
  const int KT = K / BK;
  // Prologue: fill the first STAGES-1 pipeline stages.
  #pragma unroll
  for (int s = 0; s < STAGES - 1; ++s) {
    if (s < KT) {
      load_tile(s, s);
    }
    __pipeline_commit();
  }
  for (int kt = 0; kt < KT; ++kt) {
    int next = kt + STAGES - 1;
    if (next < KT) {
      load_tile(next, next % STAGES);
    }
    __pipeline_commit();
    __pipeline_wait_prior(STAGES - 1);
    __syncthreads();
    int b = kt % STAGES;
    if (b == 0) {
      gemm(tCsA0, tCsB0, tCrC);
    } else if (b == 1) {
      gemm(tCsA1, tCsB1, tCrC);
    } else {
      gemm(tCsA2, tCsB2, tCrC);
    }
    __syncthreads();
  }
  // Fused triu epilogue.
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
      int r = m0 + tm + i * 16;
      int c = n0 + tn + j * 16;
      float v = tCrC(i, j);
      mC(r, c) = (c >= r) ? v : 0.0f;
    }
  }
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);
  int N = (int)B_c.size(1);
  TORCH_CHECK((int)B_c.size(0) == K, "B.size(0) must equal A.size(1)");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "This kernel expects M,N multiples of 128 and K multiple of 8");

  auto C = torch::empty({M, N}, A_c.options());

  auto dA = make_stride(K, Int<1>{});       // A[M,K] row-major as (M,K)
  auto dB = make_stride(Int<1>{}, N);       // B[K,N] row-major viewed as (N,K)
  auto dC = make_stride(N, Int<1>{});       // C[M,N] row-major
  auto shape_MNK = make_shape(M, N, K);

  dim3 block(256);
  dim3 grid((M + 127) / 128, (N + 127) / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triu_matmul_kernel<<<grid, block, 0, stream>>>(
      shape_MNK,
      A_c.data_ptr<float>(), dA,
      B_c.data_ptr<float>(), dB,
      C.data_ptr<float>(), dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_matmul_kernel launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

triu_mm_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=triu_mm_cpp_decl,
    cuda_sources=triu_mm_cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = triu_mm_ext

    def forward(self, A, B):
        return self._ext.triu_matmul(A, B)

