  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), sA_layout);
  Tensor sA2 = make_tensor(make_smem_ptr(smemA[2]), sA_layout);
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), sB_layout);
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), sB_layout);
  Tensor sB2 = make_tensor(make_smem_ptr(smemB[2]), sB_layout);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA2 = local_partition(sA2, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCsB2 = local_partition(sB2, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCrC = make_tensor<float>(make_shape(Int<8>{}, Int<8>{}));
  clear(tCrC);
  const int KT = K / BK;
